(function(){
 let routeApplied='',rendering=false;
 function applyRoute(){const p=location.pathname;if(/^\/learn(?:\/|$)/.test(p)){data.view='learning';routeApplied=p;return}if(routeApplied===p)return;if(p==='/'&&data.view==='learning'){data.view='dashboard';routeApplied=p;return}if(p==='/account'){data.view='account';routeApplied=p;return}let match=p.match(/^\/(gang|fighter|campaigns)\/([^/]+)(?:\/battle-session\/([^/]+))?\/?$/);if(!match)return;const [,type,raw,session]=match,key=decodeURIComponent(raw);if(type==='gang'&&data.gangs.some(g=>g.id===key)){data.view='gang';data.selectedGang=key;data.tab='fighters';routeApplied=p}else if(type==='fighter'){const g=data.gangs.find(g=>g.fighters.some(f=>f.id===key));if(g){data.view='fighter';data.selectedGang=g.id;data.selectedFighter=key;routeApplied=p}}else if(type==='campaigns'&&data.campaigns.some(c=>c.id===key)){data.view='campaign';data.selectedCampaign=key;data.campaignTab='members';routeApplied=p}if(session&&routeApplied===p){data.campaignTab='session-detail';data.selectedBattleSession=decodeURIComponent(session)}}
 function syncRoute(){if(/^\/join\//.test(location.pathname)||/^\/learn(?:\/|$)/.test(location.pathname)&&data.view==='learning')return;let path=null;if(data.view==='gang'&&gang())path='/gang/'+encodeURIComponent(gang().id);else if(data.view==='fighter'&&currentFighter())path='/fighter/'+encodeURIComponent(currentFighter().id);else if(data.view==='campaign'&&campaign()){path='/campaigns/'+encodeURIComponent(campaign().id);if(data.campaignTab==='session-detail'&&data.selectedBattleSession)path+='/battle-session/'+encodeURIComponent(data.selectedBattleSession)}else if(data.view==='account')path='/account';else if(['dashboard','catalog','gangs','campaigns'].includes(data.view))path='/';if(path&&path!==location.pathname){history.pushState({},'',path);routeApplied=path}}
 const priorRender=render;render=function(){if(rendering)return;rendering=true;try{applyRoute();priorRender();syncRoute()}finally{rendering=false}};
 const priorSave=save;save=function(...args){syncRoute();return priorSave(...args)};
 window.addEventListener('popstate',()=>{routeApplied='';if(location.pathname==='/'){data.view='dashboard';data.homeTab='gangs';routeApplied='/'}render()},true);
 render();
})();
